-- ----------------------------------------------------------------------------
-- ProjectMetadata: Project overview
-- ----------------------------------------------------------------------------
CREATE TABLE project_metadata (
  project_id                          TEXT                 PRIMARY KEY,
  name                                TEXT                ,                     -- Effortlessly Invariant Rulesbooks (ERB)
  purpose                             TEXT                ,                     -- Demonstrate that a single declarative rulebook can generate working code in multiple execution substrates (Python, Go, SQL, etc.) that all produce identical results
  architecture                        TEXT                ,                     -- Hub-and-spokes around Airtable; rulebook is the disposable IR
  repository_root                     TEXT                                      -- effortlessly-invariant-rulesbooks/
);
COMMENT ON TABLE project_metadata IS 'Project overview';
COMMENT ON COLUMN project_metadata.name IS 'Effortlessly Invariant Rulesbooks (ERB)';
COMMENT ON COLUMN project_metadata.purpose IS 'Demonstrate that a single declarative rulebook can generate working code in multiple execution substrates (Python, Go, SQL, etc.) that all produce identical results';
COMMENT ON COLUMN project_metadata.architecture IS 'Hub-and-spokes around Airtable; rulebook is the disposable IR';
COMMENT ON COLUMN project_metadata.repository_root IS 'effortlessly-invariant-rulesbooks/';

-- ----------------------------------------------------------------------------
-- ExecutionSubstrates: Runtime environments that execute business rules derived from the rulebook
-- ----------------------------------------------------------------------------
CREATE TABLE execution_substrates (
  substrate_id                        TEXT                 PRIMARY KEY,
  name                                TEXT                ,                     -- Human-readable substrate name
  technology                          TEXT                ,                     -- Language/platform (PostgreSQL, Python, Go, Excel, OWL, PlantUML, etc.)
  relative_path                       TEXT                ,                     -- Path within repo: execution-substrates/{technology}/
  injector_script                     TEXT                ,                     -- Code generation script: inject-into-{technology}.py
  test_script                         TEXT                ,                     -- Conformance test script: take-test.py
  is_production                       BOOLEAN             ,                     -- True if backed by an official Effortless tool; false if local implementation
  status                              TEXT                ,                     -- Operational status (active, proof-of-concept, deprecated)
  description                         TEXT                                      -- Purpose and capabilities
);
COMMENT ON TABLE execution_substrates IS 'Runtime environments that execute business rules derived from the rulebook';
COMMENT ON COLUMN execution_substrates.name IS 'Human-readable substrate name';
COMMENT ON COLUMN execution_substrates.technology IS 'Language/platform (PostgreSQL, Python, Go, Excel, OWL, PlantUML, etc.)';
COMMENT ON COLUMN execution_substrates.relative_path IS 'Path within repo: execution-substrates/{technology}/';
COMMENT ON COLUMN execution_substrates.injector_script IS 'Code generation script: inject-into-{technology}.py';
COMMENT ON COLUMN execution_substrates.test_script IS 'Conformance test script: take-test.py';
COMMENT ON COLUMN execution_substrates.is_production IS 'True if backed by an official Effortless tool; false if local implementation';
COMMENT ON COLUMN execution_substrates.status IS 'Operational status (active, proof-of-concept, deprecated)';
COMMENT ON COLUMN execution_substrates.description IS 'Purpose and capabilities';

